def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    counts = Counter(v for row in grid for v in row if v != 0)
    if not counts:
        return [row[:] for row in grid]

    # Tile frames form the most common nonzero color. The most frequent
    # remaining color is the ordinary interior color.
    frame = min(counts, key=lambda v: (-counts[v], v))
    interior_counts = Counter(v for row in grid for v in row
                              if v not in (0, frame))
    if not interior_counts:
        return [row[:] for row in grid]
    base = min(interior_counts, key=lambda v: (-interior_counts[v], v))

    marked = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v not in (0, frame, base):
                marked.setdefault(v, set()).add((r, c))

    out = [row[:] for row in grid]
    for color, points in marked.items():
        rows, cols = {}, {}
        for r, c in points:
            rows.setdefault(r, []).append(c)
            cols.setdefault(c, []).append(r)

        for r, cs in rows.items():
            cs.sort()
            for a, b in zip(cs, cs[1:]):
                for c in range(a + 1, b):
                    if grid[r][c] == 0:
                        out[r][c] = color

        for c, rs in cols.items():
            rs.sort()
            for a, b in zip(rs, rs[1:]):
                for r in range(a + 1, b):
                    if grid[r][c] == 0:
                        out[r][c] = color

    return out
